import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const L=JSON.parse('{"title":"PEFT（桥接）","description":"参数高效微调（LoRA/QLoRA）的工程决策桥：如何把「必须动权重」的成本降一个量级，适配器架构对部署形态的影响。","frontmatter":{"title":"PEFT（桥接）","description":"参数高效微调（LoRA/QLoRA）的工程决策桥：如何把「必须动权重」的成本降一个量级，适配器架构对部署形态的影响。","domain":"tech","tags":["tech","training","bridge","peft","lora"],"navOrder":143,"topicId":"model-lifecycle-peft","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/post-training/peft.md","filePath":"zh/tech/01-model-lifecycle/post-training/peft.md","lastUpdated":1791122193000}'),n={name:"zh/tech/01-model-lifecycle/post-training/peft.md"};function l(i,t,s,d,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<blockquote><p><strong>所在组</strong>：模型生命周期（桥接） ｜ <strong>上一组出口</strong>：理解推理基础与接口契约 ｜ <strong>本页出口</strong>：知道何时该动权重而不是改 Prompt 或上检索</p></blockquote><h1 id="peft-桥接" tabindex="-1">PEFT（桥接） <a class="header-anchor" href="#peft-桥接" aria-label="Permalink to &quot;PEFT（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：本页只回答工程决策问题。LoRA 的低秩分解数学、QLoRA 的量化组合推导在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（LoRA 对应章节）。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to &quot;解决什么问题&quot;">​</a></h2><p>**参数高效微调（Parameter-Efficient Fine-Tuning, PEFT）**是一族技术：冻结预训练模型的全量参数，只在旁边加一小块可训练参数（最流行的是 <strong>LoRA，Low-Rank Adaptation</strong>——把「对权重的修改」分解成两个低秩矩阵来学）。效果是把 SFT 的成本结构改变一个量级：</p><ul><li><strong>硬件门槛降低</strong>：消费级/单卡 GPU 可跑（对比全量微调的集群需求）。</li><li><strong>产物变小</strong>：训练产出是 MB 级「适配器」文件，而不是 GB 级的完整模型副本。</li><li><strong>一底座多适配器</strong>：服务端可共享同一个基础模型，按请求热切换不同任务的适配器——多租户定制的标准形态。</li></ul><p>一个便于记忆的类比（非严格）：全量微调是重写整本书；LoRA 是把修改写在便利贴上贴到对应页面，阅读时「原文 + 便利贴」一起生效。</p><h2 id="何时进入本页" tabindex="-1">何时进入本页 <a class="header-anchor" href="#何时进入本页" aria-label="Permalink to &quot;何时进入本页&quot;">​</a></h2><p>PEFT 不是独立决策，它是 <a href="./sft.html">SFT（桥接）</a> 决策的<strong>降成本执行方式</strong>。触发条件与 SFT 相同（prompt 与 RAG 已穷尽、有标注数据、有预算），额外多两类典型场景：</p><ol><li><strong>需要 many-variants</strong>：同一底座要出多个定制版本（按客户、按任务），全量微调每个变体的成本不可接受。</li><li><strong>本地/隐私部署</strong>：在自有硬件上跑微调后的开源模型（Llama、Mistral 等），数据不出域。</li></ol><h2 id="决策影响表" tabindex="-1">决策影响表 <a class="header-anchor" href="#决策影响表" aria-label="Permalink to &quot;决策影响表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>全量 SFT</th><th>PEFT（LoRA/QLoRA）</th></tr></thead><tbody><tr><td><strong>数据量要求</strong></td><td>同等量级的标注对（数据成本不变，未验证具体阈值）</td><td>同左——PEFT 省的是算力，不是数据</td></tr><tr><td><strong>成本结构</strong></td><td>每次训练产出完整模型副本，存储与分发贵</td><td>训练算力与存储显著降低（量级对比是社区共识，具体倍数未验证）</td></tr><tr><td><strong>推理延迟</strong></td><td>与原模型同级</td><td>底座 + 适配器合并后基本同级；注意部分托管 API 不支持外挂适配器</td></tr><tr><td><strong>维护负担</strong></td><td>每个定制版一个完整模型，版本矩阵大</td><td>底座版本 + 适配器矩阵；底座升级需回归每个适配器</td></tr><tr><td><strong>效果上限</strong></td><td>理论上限最高</td><td>绝大多数定制任务够用；极端领域迁移仍可能需要全量</td></tr></tbody></table><h2 id="与本地推理的连接" tabindex="-1">与本地推理的连接 <a class="header-anchor" href="#与本地推理的连接" aria-label="Permalink to &quot;与本地推理的连接&quot;">​</a></h2><p>如果你用 Ollama、LM Studio 等工具在本地跑模型，你已经在消费这条链路的产物——「量化模型」与「LoRA 适配器」是本地能跑大模型的两个关键前提。端侧/浏览器侧推理的展开见主线 <a href="./../../02-inference-interface/browser-edge.html">浏览器与端侧推理</a>；量化数学归 Learn LLM。</p><h2 id="lora-的工程选择项" tabindex="-1">LoRA 的工程选择项 <a class="header-anchor" href="#lora-的工程选择项" aria-label="Permalink to &quot;LoRA 的工程选择项&quot;">​</a></h2><p>决定「用 LoRA」之后还有三个工程选择，它们的推导都在 Learn LLM，此处只列决策含义：</p><ul><li><strong>秩（rank）</strong>：控制「便利贴」的表达能力。秩越高能力越强、成本越高；常见做法是从小秩起步，用评估集决定是否上调（具体推荐值未验证，以实验为准）。</li><li><strong>挂载层</strong>：只挂在注意力层还是全连接层也挂，影响效果与成本的平衡。</li><li><strong>QLoRA</strong>：先量化底座再做 LoRA 的组合拳——显存需求进一步下降，代价是训练与推理多一层量化误差。显存不够时的默认升级路径，不是效果更优的选择。</li></ul><p>这三个选择的共同点：<strong>都应由评估集驱动</strong>，而不是照抄别人的配置——「别人的秩」是在别人的数据与任务上调出来的。</p><h2 id="深层推导与实现" tabindex="-1">深层推导与实现 <a class="header-anchor" href="#深层推导与实现" aria-label="Permalink to &quot;深层推导与实现&quot;">​</a></h2><ul><li>LoRA 低秩分解的数学、秩选择、QLoRA 的量化组合 → <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 的 LoRA 章节。</li><li>原始论文：<a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">LoRA: Low-Rank Adaptation of Large Language Models</a>；实现库：<a href="https://github.com/huggingface/peft" target="_blank" rel="noreferrer">HuggingFace PEFT</a>。</li></ul>',20)])])}const m=r(n,[["render",l]]);export{L as __pageData,m as default};
